mod tests {
    use super::*;
    #[test]
    fn empty_correct_rows_do_not_count() {
        let q = Question {
            id: 0,
            text: "Question".into(),
            active: true,
            options: vec![
                OptionRow {
                    text: "One".into(),
                    correct: false,
                },
                OptionRow {
