            1,
            &[OptionRow {
                text: "Answer".into(),
                correct: true,
            }],
        )
        .unwrap();
        assert_eq!(db::questions(&db, 1).unwrap()[0].text, "First");
        db.execute("DELETE FROM quizzes WHERE id=1", []).unwrap();
        assert_eq!(
            db.query_row("SELECT COUNT(*) FROM options", [], |r| r.get::<_, i64>(0))
                .unwrap(),
            0
        );
    }
