fn save_quiz(app: &App, id: Option<i64>, fields: &Fields) -> Result<Response> {
    app.check_csrf(fields)?;
    let db = app.db()?;
    if let Some(id) = id {
        quiz_title(&db, id)?;
    }
    let title = field(fields, "title");
    if title.trim().is_empty() {
        return Ok((
            StatusCode::UNPROCESSABLE_ENTITY,
            Html(views::quiz_form(
                id,
                title,
                &app.csrf,
                &["Title is required"],
            )),
        )
            .into_response());
    }
    let id = match id {
        Some(id) => {
            db.execute(
                "UPDATE quizzes SET title = ? WHERE id = ?",
                params![title.trim(), id],
            )?;
            id
        }
        None => {
            db.execute("INSERT INTO quizzes(title) VALUES (?)", [title.trim()])?;
            db.last_insert_rowid()
        }
    };
    Ok(go_to_quiz(id))
}
